    69→  pubkey2index: PubkeyIndexMap;
    70→  index2pubkey: Index2PubkeyCache;
    71→  shufflingCache?: IShufflingCache;
    72→};
    73→
    74→export type EpochCacheOpts = {
    75→  skipSyncCommitteeCache?: boolean;
    76→  skipSyncPubkeys?: boolean;
    77→};
    78→
    79→/** Defers computing proposers by persisting only the seed, and dropping it once indexes are computed */
    80→type ProposersDeferred = {computed: false; seed: Uint8Array} | {computed: true; indexes: ValidatorIndex[]};
    81→
    82→/**
    83→ * EpochCache is the parent object of:
    84→ * - Any data-structures not part of the spec'ed BeaconState
    85→ * - Necessary to only compute data once
    86→ * - Must be kept at all times through an epoch
    87→ *
    88→ * The performance gains with EpochCache are fundamental for the BeaconNode to be able to participate in a
    89→ * production network with 100_000s of validators. In summary, it contains:
    90→ *
    91→ * Expensive data constant through the epoch:
    92→ * - pubkey cache
    93→ * - proposer indexes
    94→ * - shufflings
    95→ * - sync committee indexed
    96→ * Counters (maybe) mutated through the epoch:
    97→ * - churnLimit
    98→ * - exitQueueEpoch
    99→ * - exitQueueChurn
   100→ * Time data faster than recomputing from the state:
   101→ * - epoch
   102→ * - syncPeriod
   103→ **/
   104→export class EpochCache {
   105→  config: BeaconConfig;
   106→  /**
   107→   * Unique globally shared pubkey registry. There should only exist one for the entire application.
   108→   *
   109→   * TODO: this is a hack, we need a safety mechanism in case a bad eth1 majority vote is in,
   110→   * or handle non finalized data differently, or use an immutable.js structure for cheap copies
   111→   *
   112→   * $VALIDATOR_COUNT x 192 char String -> Number Map
   113→   */
   114→  pubkey2index: PubkeyIndexMap;
   115→  /**
   116→   * Unique globally shared pubkey registry. There should only exist one for the entire application.
   117→   *
   118→   * $VALIDATOR_COUNT x BLST deserialized pubkey (Jacobian coordinates)
   119→   */
   120→  index2pubkey: Index2PubkeyCache;
   121→  /**
   122→   * ShufflingCache is passed in from `beacon-node` so should be available at runtime but may not be
   123→   * present during testing.
   124→   */
   125→  shufflingCache?: IShufflingCache;
   126→
   127→  /**
   128→   * Indexes of the block proposers for the current epoch.
   129→   * For pre-fulu, this is computed and cached from the current shuffling.
   130→   * For post-fulu, this is copied from the state.proposerLookahead.
   131→   *
   132→   * 32 x Number
   133→   */
   134→  proposers: ValidatorIndex[];
   135→
   136→  /** Proposers for previous epoch, initialized to null in first epoch */
   137→  proposersPrevEpoch: ValidatorIndex[] | null;
   138→
   139→  /**
   140→   * The next proposer seed is only used in the getBeaconProposersNextEpoch call. It cannot be moved into
   141→   * getBeaconProposersNextEpoch because it needs state as input and all data needed by getBeaconProposersNextEpoch
   142→   * should be in the epoch context.
   143→   *
   144→   * For pre-fulu, this is lazily computed from the next epoch's shuffling.
   145→   * For post-fulu, this is copied from the state.proposerLookahead.
   146→   */
   147→  proposersNextEpoch: ProposersDeferred;
   148→
   149→  /**
   150→   * Epoch decision roots to look up correct shuffling from the Shuffling Cache
   151→   */
   152→  previousDecisionRoot: RootHex;
   153→  currentDecisionRoot: RootHex;
   154→  nextDecisionRoot: RootHex;
   155→  /**
   156→   * Shuffling of validator indexes. Immutable through the epoch, then it's replaced entirely.
   157→   * Note: Per spec definition, shuffling will always be defined. They are never called before loadState()
   158→   *
   159→   * $VALIDATOR_COUNT x Number
   160→   */
   161→  previousShuffling: EpochShuffling;
   162→  /** Same as previousShuffling */
   163→  currentShuffling: EpochShuffling;
   164→  /** Same as previousShuffling */
   165→  nextShuffling: EpochShuffling | null;
   166→  /**
   167→   * Cache nextActiveIndices so that in afterProcessEpoch the next shuffling can be build synchronously
   168→   * in case it is not built or the ShufflingCache is not available
   169→   */
   170→  nextActiveIndices: Uint32Array;
   171→  /**
   172→   * Effective balances, for altair processAttestations()
   173→   */
   174→  effectiveBalanceIncrements: EffectiveBalanceIncrements;
   175→  /**
   176→   * Total state.slashings by increment, for processSlashing()
   177→   */
   178→  totalSlashingsByIncrement: number;
   179→  syncParticipantReward: number;
   180→  syncProposerReward: number;
   181→  /**
   182→   * Update freq: once per epoch after `process_effective_balance_updates()`
   183→   */
   184→  baseRewardPerIncrement: number;
   185→  /**
   186→   * Total active balance for current epoch, to be used instead of getTotalBalance()
   187→   */
   188→  totalActiveBalanceIncrements: number;
   189→
   190→  /**
   191→   * Rate at which validators can enter or leave the set per epoch. Depends only on activeIndexes, so it does not
   192→   * change through the epoch. It's used in initiateValidatorExit(). Must be update after changing active indexes.
   193→   */
   194→  churnLimit: number;
   195→
   196→  /**
   197→   * Fork limited actual activationChurnLimit
   198→   */
   199→  activationChurnLimit: number;
   200→  /**
   201→   * Closest epoch with available churn for validators to exit at. May be updated every block as validators are
   202→   * initiateValidatorExit(). This value may vary on each fork of the state.
   203→   *
   204→   * NOTE: Changes block to block
   205→   * NOTE: No longer used by initiateValidatorExit post-electra
   206→   */
   207→  exitQueueEpoch: Epoch;
   208→  /**
   209→   * Number of validators initiating an exit at exitQueueEpoch. May be updated every block as validators are
   210→   * initiateValidatorExit(). This value may vary on each fork of the state.
   211→   *
   212→   * NOTE: Changes block to block
   213→   * NOTE: No longer used by initiateValidatorExit post-electra
   214→   */
   215→  exitQueueChurn: number;
   216→
   217→  /**
   218→   * Total cumulative balance increments through epoch for current target.
   219→   * Required for unrealized checkpoints issue pull-up tips N+1. Otherwise must run epoch transition every block
   220→   * This value is equivalent to:
   221→   * - Forward current state to end-of-epoch
   222→   * - Run beforeProcessEpoch
   223→   * - epochTransitionCache.currEpochUnslashedTargetStakeByIncrement
   224→   */
   225→  currentTargetUnslashedBalanceIncrements: number;
   226→  /**
   227→   * Total cumulative balance increments through epoch for previous target.
   228→   * Required for unrealized checkpoints issue pull-up tips N+1. Otherwise must run epoch transition every block
   229→   * This value is equivalent to:
   230→   * - Forward current state to end-of-epoch
   231→   * - Run beforeProcessEpoch
   232→   * - epochTransitionCache.prevEpochUnslashedStake.targetStakeByIncrement
   233→   */
   234→  previousTargetUnslashedBalanceIncrements: number;
   235→
   236→  /** TODO: Indexed SyncCommitteeCache */
   237→  currentSyncCommitteeIndexed: SyncCommitteeCache;
   238→  /** TODO: Indexed SyncCommitteeCache */
   239→  nextSyncCommitteeIndexed: SyncCommitteeCache;
   240→
   241→  // TODO: Helper stats
   242→  syncPeriod: SyncPeriod;
   243→
   244→  epoch: Epoch;
   245→
   246→  get nextEpoch(): Epoch {
   247→    return this.epoch + 1;
   248→  }
   249→
   250→  constructor(data: {
   251→    config: BeaconConfig;
   252→    pubkey2index: PubkeyIndexMap;
   253→    index2pubkey: Index2PubkeyCache;
   254→    shufflingCache?: IShufflingCache;
   255→    proposers: number[];
   256→    proposersPrevEpoch: number[] | null;
   257→    proposersNextEpoch: ProposersDeferred;
   258→    previousDecisionRoot: RootHex;
   259→    currentDecisionRoot: RootHex;
   260→    nextDecisionRoot: RootHex;
   261→    previousShuffling: EpochShuffling;
   262→    currentShuffling: EpochShuffling;
   263→    nextShuffling: EpochShuffling | null;
   264→    nextActiveIndices: Uint32Array;
   265→    effectiveBalanceIncrements: EffectiveBalanceIncrements;
   266→    totalSlashingsByIncrement: number;
   267→    syncParticipantReward: number;
   268→    syncProposerReward: number;
   269→    baseRewardPerIncrement: number;
   270→    totalActiveBalanceIncrements: number;
   271→    churnLimit: number;
   272→    activationChurnLimit: number;
   273→    exitQueueEpoch: Epoch;
   274→    exitQueueChurn: number;
   275→    currentTargetUnslashedBalanceIncrements: number;
   276→    previousTargetUnslashedBalanceIncrements: number;
   277→    currentSyncCommitteeIndexed: SyncCommitteeCache;
   278→    nextSyncCommitteeIndexed: SyncCommitteeCache;
   279→    epoch: Epoch;
   280→    syncPeriod: SyncPeriod;
   281→  }) {
   282→    this.config = data.config;
   283→    this.pubkey2index = data.pubkey2index;
   284→    this.index2pubkey = data.index2pubkey;
   285→    this.shufflingCache = data.shufflingCache;
   286→    this.proposers = data.proposers;
   287→    this.proposersPrevEpoch = data.proposersPrevEpoch;
   288→    this.proposersNextEpoch = data.proposersNextEpoch;
   289→    this.previousDecisionRoot = data.previousDecisionRoot;
   290→    this.currentDecisionRoot = data.currentDecisionRoot;
   291→    this.nextDecisionRoot = data.nextDecisionRoot;
   292→    this.previousShuffling = data.previousShuffling;
   293→    this.currentShuffling = data.currentShuffling;
   294→    this.nextShuffling = data.nextShuffling;
   295→    this.nextActiveIndices = data.nextActiveIndices;
   296→    this.effectiveBalanceIncrements = data.effectiveBalanceIncrements;
   297→    this.totalSlashingsByIncrement = data.totalSlashingsByIncrement;
   298→    this.syncParticipantReward = data.syncParticipantReward;
   299→    this.syncProposerReward = data.syncProposerReward;
   300→    this.baseRewardPerIncrement = data.baseRewardPerIncrement;
   301→    this.totalActiveBalanceIncrements = data.totalActiveBalanceIncrements;
   302→    this.churnLimit = data.churnLimit;
   303→    this.activationChurnLimit = data.activationChurnLimit;
   304→    this.exitQueueEpoch = data.exitQueueEpoch;
   305→    this.exitQueueChurn = data.exitQueueChurn;
   306→    this.currentTargetUnslashedBalanceIncrements = data.currentTargetUnslashedBalanceIncrements;
   307→    this.previousTargetUnslashedBalanceIncrements = data.previousTargetUnslashedBalanceIncrements;
   308→    this.currentSyncCommitteeIndexed = data.currentSyncCommitteeIndexed;
   309→    this.nextSyncCommitteeIndexed = data.nextSyncCommitteeIndexed;
   310→    this.epoch = data.epoch;
   311→    this.syncPeriod = data.syncPeriod;
   312→  }
   313→
   314→  /**
   315→   * Create an epoch cache
   316→   * @param state a finalized beacon state. Passing in unfinalized state may cause unexpected behaviour
   317→   *
   318→   * SLOW CODE - 🐢
   319→   */
   320→  static createFromState(
   321→    state: BeaconStateAllForks,
   322→    {config, pubkey2index, index2pubkey, shufflingCache}: EpochCacheImmutableData,
   323→    opts?: EpochCacheOpts
   324→  ): EpochCache {
   325→    const currentEpoch = computeEpochAtSlot(state.slot);
   326→    const isGenesis = currentEpoch === GENESIS_EPOCH;
   327→    const previousEpoch = isGenesis ? GENESIS_EPOCH : currentEpoch - 1;
   328→    const nextEpoch = currentEpoch + 1;
   329→
   330→    let totalActiveBalanceIncrements = 0;
   331→    let exitQueueEpoch = computeActivationExitEpoch(currentEpoch);
   332→    let exitQueueChurn = 0;
   333→
   334→    const validators = state.validators.getAllReadonlyValues();
   335→    const validatorCount = validators.length;
   336→
   337→    // syncPubkeys here to ensure EpochCacheImmutableData is popualted before computing the rest of caches
   338→    // - computeSyncCommitteeCache() needs a fully populated pubkey2index cache
   339→    if (!opts?.skipSyncPubkeys) {
   340→      syncPubkeys(validators, pubkey2index, index2pubkey);
   341→    }
   342→
   343→    const effectiveBalanceIncrements = getEffectiveBalanceIncrementsWithLen(validatorCount);
   344→    const totalSlashingsByIncrement = getTotalSlashingsByIncrement(state);
   345→    const previousActiveIndicesAsNumberArray: ValidatorIndex[] = [];
   346→    const currentActiveIndicesAsNumberArray: ValidatorIndex[] = [];
   347→    const nextActiveIndicesAsNumberArray: ValidatorIndex[] = [];
   348→
   349→    // BeaconChain could provide a shuffling cache to avoid re-computing shuffling every epoch
   350→    // in that case, we don't need to compute shufflings again
   351→    const previousDecisionRoot = calculateShufflingDecisionRoot(config, state, previousEpoch);
   352→    const cachedPreviousShuffling = shufflingCache?.getSync(previousEpoch, previousDecisionRoot);
   353→    const currentDecisionRoot = calculateShufflingDecisionRoot(config, state, currentEpoch);
   354→    const cachedCurrentShuffling = shufflingCache?.getSync(currentEpoch, currentDecisionRoot);
   355→    const nextDecisionRoot = calculateShufflingDecisionRoot(config, state, nextEpoch);
   356→    const cachedNextShuffling = shufflingCache?.getSync(nextEpoch, nextDecisionRoot);
   357→
   358→    for (let i = 0; i < validatorCount; i++) {
   359→      const validator = validators[i];
   360→
   361→      // Note: Not usable for fork-choice balances since in-active validators are not zero'ed
   362→      effectiveBalanceIncrements[i] = Math.floor(validator.effectiveBalance / EFFECTIVE_BALANCE_INCREMENT);
   363→
   364→      // we only need to track active indices for previous, current and next epoch if we have to compute shufflings
   365→      // skip doing that if we already have cached shufflings
   366→      if (cachedPreviousShuffling == null && isActiveValidator(validator, previousEpoch)) {
   367→        previousActiveIndicesAsNumberArray.push(i);
   368→      }
   369→      if (isActiveValidator(validator, currentEpoch)) {
   370→        if (cachedCurrentShuffling == null) {
   371→          currentActiveIndicesAsNumberArray.push(i);
   372→        }
   373→        // We track totalActiveBalanceIncrements as ETH to fit total network balance in a JS number (53 bits)
   374→        totalActiveBalanceIncrements += effectiveBalanceIncrements[i];
   375→      }
   376→      if (cachedNextShuffling == null && isActiveValidator(validator, nextEpoch)) {
   377→        nextActiveIndicesAsNumberArray.push(i);
   378→      }
   379→
   380→      const {exitEpoch} = validator;
   381→      if (exitEpoch !== FAR_FUTURE_EPOCH) {
   382→        if (exitEpoch > exitQueueEpoch) {
   383→          exitQueueEpoch = exitEpoch;
   384→          exitQueueChurn = 1;
   385→        } else if (exitEpoch === exitQueueEpoch) {
   386→          exitQueueChurn += 1;
   387→        }
   388→      }
   389→    }
   390→
   391→    // Spec: `EFFECTIVE_BALANCE_INCREMENT` Gwei minimum to avoid divisions by zero
   392→    // 1 = 1 unit of EFFECTIVE_BALANCE_INCREMENT
   393→    if (totalActiveBalanceIncrements < 1) {
   394→      totalActiveBalanceIncrements = 1;
   395→    } else if (totalActiveBalanceIncrements >= Number.MAX_SAFE_INTEGER) {
   396→      throw Error("totalActiveBalanceIncrements >= Number.MAX_SAFE_INTEGER. MAX_EFFECTIVE_BALANCE is too low.");
   397→    }
   398→
   399→    const nextActiveIndices = new Uint32Array(nextActiveIndicesAsNumberArray);
   400→    let previousShuffling: EpochShuffling;
   401→    let currentShuffling: EpochShuffling;
   402→    let nextShuffling: EpochShuffling;
   403→
   404→    if (!shufflingCache) {
   405→      // Only for testing. shufflingCache should always be available in prod
   406→      previousShuffling = computeEpochShuffling(
   407→        state,
   408→        new Uint32Array(previousActiveIndicesAsNumberArray),
   409→        previousEpoch
   410→      );
   411→
   412→      currentShuffling = isGenesis
   413→        ? previousShuffling
   414→        : computeEpochShuffling(state, new Uint32Array(currentActiveIndicesAsNumberArray), currentEpoch);
   415→
   416→      nextShuffling = computeEpochShuffling(state, nextActiveIndices, nextEpoch);
   417→    } else {
   418→      currentShuffling = cachedCurrentShuffling
   419→        ? cachedCurrentShuffling
   420→        : shufflingCache.getSync(currentEpoch, currentDecisionRoot, {
   421→            state,
   422→            activeIndices: new Uint32Array(currentActiveIndicesAsNumberArray),
   423→          });
   424→
   425→      previousShuffling = cachedPreviousShuffling
   426→        ? cachedPreviousShuffling
   427→        : isGenesis
   428→          ? currentShuffling
   429→          : shufflingCache.getSync(previousEpoch, previousDecisionRoot, {
   430→              state,
   431→              activeIndices: new Uint32Array(previousActiveIndicesAsNumberArray),
   432→            });
   433→
   434→      nextShuffling = cachedNextShuffling
   435→        ? cachedNextShuffling
   436→        : shufflingCache.getSync(nextEpoch, nextDecisionRoot, {
   437→            state,
   438→            activeIndices: nextActiveIndices,
   439→          });
   440→    }
   441→
   442→    const currentProposerSeed = getSeed(state, currentEpoch, DOMAIN_BEACON_PROPOSER);
   443→
   444→    let proposers: number[];
   445→    if (currentEpoch >= config.FULU_FORK_EPOCH) {
   446→      // Overwrite proposers with state.proposerLookahead
   447→      proposers = (state as CachedBeaconStateFulu).proposerLookahead.getAll().slice(0, SLOTS_PER_EPOCH);
   448→    } else {
   449→      // We need to calculate Pre-fulu
   450→      // Allow to create CachedBeaconState for empty states, or no active validators
   451→      proposers =
   452→        currentShuffling.activeIndices.length > 0
   453→          ? computeProposers(
   454→              config.getForkSeqAtEpoch(currentEpoch),
   455→              currentProposerSeed,
   456→              currentShuffling,
   457→              effectiveBalanceIncrements
   458→            )
   459→          : [];
   460→    }
   461→
   462→    const proposersNextEpoch: ProposersDeferred = {
   463→      computed: false,
   464→      seed: getSeed(state, nextEpoch, DOMAIN_BEACON_PROPOSER),
   465→    };
   466→
   467→    // Only after altair, compute the indices of the current sync committee
   468→    const afterAltairFork = currentEpoch >= config.ALTAIR_FORK_EPOCH;
   469→
   470→    // Values syncParticipantReward, syncProposerReward, baseRewardPerIncrement are only used after altair.
   471→    // However, since they are very cheap to compute they are computed always to simplify upgradeState function.
   472→    const syncParticipantReward = computeSyncParticipantReward(totalActiveBalanceIncrements);
   473→    const syncProposerReward = Math.floor(syncParticipantReward * PROPOSER_WEIGHT_FACTOR);
   474→    const baseRewardPerIncrement = computeBaseRewardPerIncrement(totalActiveBalanceIncrements);
   475→
   476→    let currentSyncCommitteeIndexed: SyncCommitteeCache;
   477→    let nextSyncCommitteeIndexed: SyncCommitteeCache;
   478→    // Allow to skip populating sync committee for initializeBeaconStateFromEth1()
   479→    if (afterAltairFork && !opts?.skipSyncCommitteeCache) {
   480→      const altairState = state as BeaconStateAltair;
   481→      currentSyncCommitteeIndexed = computeSyncCommitteeCache(altairState.currentSyncCommittee, pubkey2index);
   482→      nextSyncCommitteeIndexed = computeSyncCommitteeCache(altairState.nextSyncCommittee, pubkey2index);
   483→    } else {
   484→      currentSyncCommitteeIndexed = new SyncCommitteeCacheEmpty();
   485→      nextSyncCommitteeIndexed = new SyncCommitteeCacheEmpty();
   486→    }
   487→
   488→    // Precompute churnLimit for efficient initiateValidatorExit() during block proposing MUST be recompute everytime the
   489→    // active validator indices set changes in size. Validators change active status only when:
   490→    // - validator.activation_epoch is set. Only changes in process_registry_updates() if validator can be activated. If
   491→    //   the value changes it will be set to `epoch + 1 + MAX_SEED_LOOKAHEAD`.
   492→    // - validator.exit_epoch is set. Only changes in initiate_validator_exit() if validator exits. If the value changes,
   493→    //   it will be set to at least `epoch + 1 + MAX_SEED_LOOKAHEAD`.
   494→    // ```
   495→    // is_active_validator = validator.activation_epoch <= epoch < validator.exit_epoch
   496→    // ```
   497→    // So the returned value of is_active_validator(epoch) is guaranteed to not change during `MAX_SEED_LOOKAHEAD` epochs.
   498→    //
   499→    // activeIndices size is dependent on the state epoch. The epoch is advanced after running the epoch transition, and
   500→    // the first block of the epoch process_block() call. So churnLimit must be computed at the end of the before epoch
   501→    // transition and the result is valid until the end of the next epoch transition
   502→    const churnLimit = getChurnLimit(config, currentShuffling.activeIndices.length);
   503→    const activationChurnLimit = getActivationChurnLimit(
   504→      config,
   505→      config.getForkSeq(state.slot),
   506→      currentShuffling.activeIndices.length
   507→    );
   508→    if (exitQueueChurn >= churnLimit) {
   509→      exitQueueEpoch += 1;
   510→      exitQueueChurn = 0;
   511→    }
   512→
   513→    // TODO: describe issue. Compute progressive target balances
   514→    // Compute balances from zero, note this state could be mid-epoch so target balances != 0
   515→    let previousTargetUnslashedBalanceIncrements = 0;
   516→    let currentTargetUnslashedBalanceIncrements = 0;
   517→
   518→    if (config.getForkSeq(state.slot) >= ForkSeq.altair) {
   519→      const {previousEpochParticipation, currentEpochParticipation} = state as BeaconStateAltair;
   520→      previousTargetUnslashedBalanceIncrements = sumTargetUnslashedBalanceIncrements(
   521→        previousEpochParticipation.getAll(),
   522→        previousEpoch,
   523→        validators
   524→      );
   525→      currentTargetUnslashedBalanceIncrements = sumTargetUnslashedBalanceIncrements(
   526→        currentEpochParticipation.getAll(),
   527→        currentEpoch,
   528→        validators
   529→      );
   530→    }
   531→
   532→    return new EpochCache({
   533→      config,
   534→      pubkey2index,
   535→      index2pubkey,
   536→      shufflingCache,
   537→      proposers,
   538→      // On first epoch, set to null to prevent unnecessary work since this is only used for metrics
   539→      proposersPrevEpoch: null,
   540→      proposersNextEpoch,
   541→      previousDecisionRoot,
   542→      currentDecisionRoot,
   543→      nextDecisionRoot,
   544→      previousShuffling,
   545→      currentShuffling,
   546→      nextShuffling,
   547→      nextActiveIndices,
   548→      effectiveBalanceIncrements,
   549→      totalSlashingsByIncrement,
   550→      syncParticipantReward,
   551→      syncProposerReward,
   552→      baseRewardPerIncrement,
   553→      totalActiveBalanceIncrements,
   554→      churnLimit,
   555→      activationChurnLimit,
   556→      exitQueueEpoch,
   557→      exitQueueChurn,
   558→      previousTargetUnslashedBalanceIncrements,
   559→      currentTargetUnslashedBalanceIncrements,
   560→      currentSyncCommitteeIndexed,
   561→      nextSyncCommitteeIndexed,
   562→      epoch: currentEpoch,
   563→      syncPeriod: computeSyncPeriodAtEpoch(currentEpoch),
   564→    });
   565→  }
