   567→  /**
   568→   * Copies a given EpochCache while avoiding copying its immutable parts.
   569→   */
   570→  clone(): EpochCache {
   571→    // warning: pubkey cache is not copied, it is shared, as eth1 is not expected to reorder validators.
   572→    // Shallow copy all data from current epoch context to the next
   573→    // All data is completely replaced, or only-appended
   574→    return new EpochCache({
   575→      config: this.config,
   576→      // Common append-only structures shared with all states, no need to clone
   577→      pubkey2index: this.pubkey2index,
   578→      index2pubkey: this.index2pubkey,
   579→      shufflingCache: this.shufflingCache,
   580→      // Immutable data
   581→      proposers: this.proposers,
   582→      proposersPrevEpoch: this.proposersPrevEpoch,
   583→      proposersNextEpoch: this.proposersNextEpoch,
   584→      previousDecisionRoot: this.previousDecisionRoot,
   585→      currentDecisionRoot: this.currentDecisionRoot,
   586→      nextDecisionRoot: this.nextDecisionRoot,
   587→      previousShuffling: this.previousShuffling,
   588→      currentShuffling: this.currentShuffling,
   589→      nextShuffling: this.nextShuffling,
   590→      nextActiveIndices: this.nextActiveIndices,
   591→      // Uint8Array, requires cloning, but it is cloned only when necessary before an epoch transition
   592→      // See EpochCache.beforeEpochTransition()
   593→      effectiveBalanceIncrements: this.effectiveBalanceIncrements,
   594→      totalSlashingsByIncrement: this.totalSlashingsByIncrement,
   595→      // Basic types (numbers) cloned implicitly
   596→      syncParticipantReward: this.syncParticipantReward,
   597→      syncProposerReward: this.syncProposerReward,
   598→      baseRewardPerIncrement: this.baseRewardPerIncrement,
   599→      totalActiveBalanceIncrements: this.totalActiveBalanceIncrements,
   600→      churnLimit: this.churnLimit,
   601→      activationChurnLimit: this.activationChurnLimit,
   602→      exitQueueEpoch: this.exitQueueEpoch,
   603→      exitQueueChurn: this.exitQueueChurn,
   604→      previousTargetUnslashedBalanceIncrements: this.previousTargetUnslashedBalanceIncrements,
   605→      currentTargetUnslashedBalanceIncrements: this.currentTargetUnslashedBalanceIncrements,
   606→      currentSyncCommitteeIndexed: this.currentSyncCommitteeIndexed,
   607→      nextSyncCommitteeIndexed: this.nextSyncCommitteeIndexed,
   608→      epoch: this.epoch,
   609→      syncPeriod: this.syncPeriod,
   610→    });
   611→  }
   612→
   613→  /**
   614→   * Called to re-use information, such as the shuffling of the next epoch, after transitioning into a
   615→   * new epoch. Also handles pre-computation of values that may change during the upcoming epoch and
   616→   * that get used in the following epoch transition.  Often those pre-computations are not used by the
   617→   * chain but are courtesy values that are served via the API for epoch look ahead of duties.
   618→   *
   619→   * Steps for afterProcessEpoch
   620→   * 1) update previous/current/next values of cached items
   621→   *
   622→   * At fork boundary, this runs pre-fork logic and it happens before `upgradeState*` is called.
   623→   */
   624→  afterProcessEpoch(state: CachedBeaconStateAllForks, epochTransitionCache: EpochTransitionCache): void {
   625→    // Because the slot was incremented before entering this function the "next epoch" is actually the "current epoch"
   626→    // in this context but that is not actually true because the state transition happens in the last 4 seconds of the
   627→    // epoch. For the context of this function "upcoming epoch" is used to denote the epoch that will begin after this
   628→    // function returns.  The epoch that is "next" once the state transition is complete is referred to as the
   629→    // epochAfterUpcoming for the same reason to help minimize confusion.
   630→    const upcomingEpoch = this.nextEpoch;
   631→    const epochAfterUpcoming = upcomingEpoch + 1;
   632→
   633→    // move current to previous
   634→    this.previousShuffling = this.currentShuffling;
   635→    this.previousDecisionRoot = this.currentDecisionRoot;
   636→
   637→    // move next to current or calculate upcoming
   638→    this.currentDecisionRoot = this.nextDecisionRoot;
   639→    if (this.nextShuffling) {
   640→      // was already pulled from the ShufflingCache to the EpochCache (should be in most cases)
   641→      this.currentShuffling = this.nextShuffling;
   642→    } else {
   643→      this.shufflingCache?.metrics?.shufflingCache.nextShufflingNotOnEpochCache.inc();
   644→      this.currentShuffling =
   645→        this.shufflingCache?.getSync(upcomingEpoch, this.currentDecisionRoot, {
   646→          state,
   647→          // have to use the "nextActiveIndices" that were saved in the last transition here to calculate
   648→          // the upcoming shuffling if it is not already built (similar condition to the below computation)
   649→          activeIndices: this.nextActiveIndices,
   650→        }) ??
   651→        // allow for this case during testing where the ShufflingCache is not present, may affect perf testing
   652→        // so should be taken into account when structuring tests.  Should not affect unit or other tests though
   653→        computeEpochShuffling(state, this.nextActiveIndices, upcomingEpoch);
   654→    }
   655→
   656→    // handle next values
   657→    this.nextDecisionRoot = epochTransitionCache.nextShufflingDecisionRoot;
   658→    this.nextActiveIndices = epochTransitionCache.nextShufflingActiveIndices;
   659→    if (this.shufflingCache) {
   660→      if (!epochTransitionCache.asyncShufflingCalculation) {
   661→        this.nextShuffling = this.shufflingCache.getSync(epochAfterUpcoming, this.nextDecisionRoot, {
   662→          state,
   663→          activeIndices: this.nextActiveIndices,
   664→        });
   665→      } else {
   666→        this.nextShuffling = null;
   667→        // This promise will resolve immediately after the synchronous code of the state-transition runs. Until
   668→        // the build is done on a worker thread it will be calculated immediately after the epoch transition
   669→        // completes.  Once the work is done concurrently it should be ready by time this get runs so the promise
   670→        // will resolve directly on the next spin of the event loop because the epoch transition and shuffling take
   671→        // about the same time to calculate so theoretically its ready now.  Do not await here though in case it
   672→        // is not ready yet as the transition must not be asynchronous.
   673→        this.shufflingCache
   674→          .get(epochAfterUpcoming, this.nextDecisionRoot)
   675→          .then((shuffling) => {
   676→            if (!shuffling) {
   677→              throw new Error("EpochShuffling not returned from get in afterProcessEpoch");
   678→            }
   679→            this.nextShuffling = shuffling;
   680→          })
   681→          .catch((err) => {
   682→            this.shufflingCache?.logger?.error(
   683→              "EPOCH_CONTEXT_SHUFFLING_BUILD_ERROR",
   684→              {epoch: epochAfterUpcoming, decisionRoot: epochTransitionCache.nextShufflingDecisionRoot},
   685→              err
   686→            );
   687→          });
   688→      }
   689→    } else {
   690→      // Only for testing. shufflingCache should always be available in prod
   691→      this.nextShuffling = computeEpochShuffling(state, this.nextActiveIndices, epochAfterUpcoming);
   692→    }
   693→
   694→    // TODO: DEDUPLICATE from createEpochCache
   695→    //
   696→    // Precompute churnLimit for efficient initiateValidatorExit() during block proposing MUST be recompute every time the
   697→    // active validator indices set changes in size. Validators change active status only when:
   698→    // - validator.activation_epoch is set. Only changes in process_registry_updates() if validator can be activated. If
   699→    //   the value changes it will be set to `epoch + 1 + MAX_SEED_LOOKAHEAD`.
   700→    // - validator.exit_epoch is set. Only changes in initiate_validator_exit() if validator exits. If the value changes,
   701→    //   it will be set to at least `epoch + 1 + MAX_SEED_LOOKAHEAD`.
   702→    // ```
   703→    // is_active_validator = validator.activation_epoch <= epoch < validator.exit_epoch
   704→    // ```
   705→    // So the returned value of is_active_validator(epoch) is guaranteed to not change during `MAX_SEED_LOOKAHEAD` epochs.
   706→    //
   707→    // activeIndices size is dependent on the state epoch. The epoch is advanced after running the epoch transition, and
   708→    // the first block of the epoch process_block() call. So churnLimit must be computed at the end of the before epoch
   709→    // transition and the result is valid until the end of the next epoch transition
   710→    this.churnLimit = getChurnLimit(this.config, this.currentShuffling.activeIndices.length);
   711→    this.activationChurnLimit = getActivationChurnLimit(
   712→      this.config,
   713→      this.config.getForkSeq(state.slot),
   714→      this.currentShuffling.activeIndices.length
   715→    );
   716→
   717→    // Maybe advance exitQueueEpoch at the end of the epoch if there haven't been any exists for a while
   718→    const exitQueueEpoch = computeActivationExitEpoch(upcomingEpoch);
   719→    if (exitQueueEpoch > this.exitQueueEpoch) {
   720→      this.exitQueueEpoch = exitQueueEpoch;
   721→      this.exitQueueChurn = 0;
   722→    }
   723→
   724→    this.totalActiveBalanceIncrements = epochTransitionCache.nextEpochTotalActiveBalanceByIncrement;
   725→    if (upcomingEpoch >= this.config.ALTAIR_FORK_EPOCH) {
   726→      this.syncParticipantReward = computeSyncParticipantReward(this.totalActiveBalanceIncrements);
   727→      this.syncProposerReward = Math.floor(this.syncParticipantReward * PROPOSER_WEIGHT_FACTOR);
   728→      this.baseRewardPerIncrement = computeBaseRewardPerIncrement(this.totalActiveBalanceIncrements);
   729→    }
   730→
   731→    this.previousTargetUnslashedBalanceIncrements = this.currentTargetUnslashedBalanceIncrements;
   732→    this.currentTargetUnslashedBalanceIncrements = 0;
   733→
   734→    // Advance time units
   735→    // state.slot is advanced right before calling this function
   736→    // ```
   737→    // postState.slot++;
   738→    // afterProcessEpoch(postState, epochTransitionCache);
   739→    // ```
   740→    this.epoch = computeEpochAtSlot(state.slot);
   741→    this.syncPeriod = computeSyncPeriodAtEpoch(this.epoch);
   742→  }
   743→
   744→  /**
   745→   * At fork boundary, this runs post-fork logic and it happens after `upgradeState*` is called.
   746→   */
   747→  finalProcessEpoch(state: CachedBeaconStateAllForks): void {
   748→    // this.epoch was updated at the end of afterProcessEpoch()
   749→    const upcomingEpoch = this.epoch;
   750→    const epochAfterUpcoming = upcomingEpoch + 1;
   751→
   752→    this.proposersPrevEpoch = this.proposers;
   753→    if (upcomingEpoch >= this.config.FULU_FORK_EPOCH) {
   754→      // Populate proposer cache with lookahead from state
   755→      const proposerLookahead = (state as CachedBeaconStateFulu).proposerLookahead.getAll();
   756→      this.proposers = proposerLookahead.slice(0, SLOTS_PER_EPOCH);
   757→
   758→      if (proposerLookahead.length >= SLOTS_PER_EPOCH * 2) {
   759→        this.proposersNextEpoch = {
   760→          computed: true,
   761→          indexes: proposerLookahead.slice(SLOTS_PER_EPOCH, SLOTS_PER_EPOCH * 2),
   762→        };
   763→      } else {
   764→        // This should not happen unless MIN_SEED_LOOKAHEAD is set to 0
   765→        // this ensures things don't break if the proposer lookahead is not long enough
   766→        this.proposersNextEpoch = {computed: false, seed: getSeed(state, epochAfterUpcoming, DOMAIN_BEACON_PROPOSER)};
   767→      }
   768→    } else {
   769→      // Need to calculate proposers pre-fulu
   770→      const upcomingProposerSeed = getSeed(state, upcomingEpoch, DOMAIN_BEACON_PROPOSER);
   771→      // next epoch was moved to current epoch so use current here
   772→      this.proposers = computeProposers(
   773→        this.config.getForkSeqAtEpoch(upcomingEpoch),
   774→        upcomingProposerSeed,
   775→        this.currentShuffling,
   776→        this.effectiveBalanceIncrements
   777→      );
   778→      // Only pre-compute the seed since it's very cheap. Do the expensive computeProposers() call only on demand.
   779→      this.proposersNextEpoch = {computed: false, seed: getSeed(state, epochAfterUpcoming, DOMAIN_BEACON_PROPOSER)};
   780→    }
   781→  }
   782→
   783→  beforeEpochTransition(): void {
   784→    // Clone (copy) before being mutated in processEffectiveBalanceUpdates
   785→    // NOTE: Force to use Uint16Array.slice (copy) instead of Buffer.call (not copy)
   786→    this.effectiveBalanceIncrements = Uint16Array.prototype.slice.call(this.effectiveBalanceIncrements, 0);
   787→  }
