   789→  /**
   790→   * Return the beacon committee at slot for index.
   791→   */
   792→  getBeaconCommittee(slot: Slot, index: CommitteeIndex): Uint32Array {
   793→    return this.getBeaconCommittees(slot, [index])[0];
   794→  }
   795→
   796→  /**
   797→   * Return a Uint32Array[] representing committees of indices
   798→   */
   799→  getBeaconCommittees(slot: Slot, indices: CommitteeIndex[]): Uint32Array[] {
   800→    if (indices.length === 0) {
   801→      throw new Error("Attempt to get committees without providing CommitteeIndex");
   802→    }
   803→
   804→    const slotCommittees = this.getShufflingAtSlot(slot).committees[slot % SLOTS_PER_EPOCH];
   805→    const committees = [];
   806→
   807→    for (const index of indices) {
   808→      if (index >= slotCommittees.length) {
   809→        throw new EpochCacheError({
   810→          code: EpochCacheErrorCode.COMMITTEE_INDEX_OUT_OF_RANGE,
   811→          index,
   812→          maxIndex: slotCommittees.length,
   813→        });
   814→      }
   815→      committees.push(slotCommittees[index]);
   816→    }
   817→
   818→    return committees;
   819→  }
   820→
   821→  getCommitteeCountPerSlot(epoch: Epoch): number {
   822→    return this.getShufflingAtEpoch(epoch).committeesPerSlot;
   823→  }
   824→
   825→  /**
   826→   * Compute the correct subnet for a slot/committee index
   827→   */
   828→  computeSubnetForSlot(slot: number, committeeIndex: number): SubnetID {
   829→    const slotsSinceEpochStart = slot % SLOTS_PER_EPOCH;
   830→    const committeesPerSlot = this.getCommitteeCountPerSlot(computeEpochAtSlot(slot));
   831→    const committeesSinceEpochStart = committeesPerSlot * slotsSinceEpochStart;
   832→    return (committeesSinceEpochStart + committeeIndex) % ATTESTATION_SUBNET_COUNT;
   833→  }
   834→
   835→  /**
   836→   * Read from proposers instead of state.proposer_lookahead because we set it in `finalProcessEpoch()`
   837→   * See https://github.com/ethereum/consensus-specs/blob/e9266b2145c09b63ba0039a9f477cfe8a629c78b/specs/fulu/beacon-chain.md#modified-get_beacon_proposer_index
   838→   */
   839→  getBeaconProposer(slot: Slot): ValidatorIndex {
   840→    const epoch = computeEpochAtSlot(slot);
   841→    if (epoch !== this.currentShuffling.epoch) {
   842→      throw new EpochCacheError({
   843→        code: EpochCacheErrorCode.PROPOSER_EPOCH_MISMATCH,
   844→        currentEpoch: this.currentShuffling.epoch,
   845→        requestedEpoch: epoch,
   846→      });
   847→    }
   848→    return this.proposers[slot % SLOTS_PER_EPOCH];
   849→  }
   850→
   851→  getBeaconProposers(): ValidatorIndex[] {
   852→    return this.proposers;
   853→  }
   854→
   855→  getBeaconProposersPrevEpoch(): ValidatorIndex[] | null {
   856→    return this.proposersPrevEpoch;
   857→  }
   858→
   859→  /**
   860→   * We allow requesting proposal duties 1 epoch in the future as in normal network conditions it's possible to predict
   861→   * the correct shuffling with high probability. While knowing the proposers in advance is not useful for consensus,
   862→   * users want to know it to plan manteinance and avoid missing block proposals.
   863→   *
   864→   * **How to predict future proposers**
   865→   *
   866→   * Proposer duties for epoch N are guaranteed to be known at epoch N. Proposer duties depend exclusively on:
   867→   * 1. seed (from randao_mix): known 2 epochs ahead
   868→   * 2. active validator set: known 4 epochs ahead
   869→   * 3. effective balance: not known ahead
   870→   *
   871→   * ```python
   872→   * def get_beacon_proposer_index(state: BeaconState) -> ValidatorIndex:
   873→   *   epoch = get_current_epoch(state)
   874→   *   seed = hash(get_seed(state, epoch, DOMAIN_BEACON_PROPOSER) + uint_to_bytes(state.slot))
   875→   *   indices = get_active_validator_indices(state, epoch)
   876→   *   return compute_proposer_index(state, indices, seed)
   877→   * ```
   878→   *
   879→   * **1**: If `MIN_SEED_LOOKAHEAD = 1` the randao_mix used for the seed is from 2 epochs ago. So at epoch N, the seed
   880→   * is known and unchangable for duties at epoch N+1 and N+2 for proposer duties.
   881→   *
   882→   * ```python
   883→   * def get_seed(state: BeaconState, epoch: Epoch, domain_type: DomainType) -> Bytes32:
   884→   *   mix = get_randao_mix(state, Epoch(epoch - MIN_SEED_LOOKAHEAD - 1))
   885→   *   return hash(domain_type + uint_to_bytes(epoch) + mix)
   886→   * ```
   887→   *
   888→   * **2**: The active validator set can be predicted `MAX_SEED_LOOKAHEAD` in advance due to how activations are
   889→   * processed. We already compute the active validator set for the next epoch to optimize epoch processing, so it's
   890→   * reused here.
   891→   *
   892→   * **3**: Effective balance is not known ahead of time, but it rarely changes. Even if it changes, only a few
   893→   * balances are sampled to adjust the probability of the next selection (32 per epoch on average). So to invalidate
   894→   * the prediction the effective of one of those 32 samples should change and change the random_byte inequality.
   895→   */
   896→  getBeaconProposersNextEpoch(): ValidatorIndex[] {
   897→    if (!this.proposersNextEpoch.computed) {
   898→      // this is lazily computed pre-fulu
   899→      const indexes = computeProposers(
   900→        this.config.getForkSeqAtEpoch(this.nextEpoch),
   901→        this.proposersNextEpoch.seed,
   902→        this.getShufflingAtEpoch(this.nextEpoch),
   903→        this.effectiveBalanceIncrements
   904→      );
   905→      this.proposersNextEpoch = {computed: true, indexes};
   906→    }
   907→
   908→    // this is eagerly computed post-fulu
   909→    return this.proposersNextEpoch.indexes;
   910→  }
   911→
   912→  /**
   913→   * Return the indexed attestation corresponding to ``attestation``.
   914→   */
   915→  getIndexedAttestation(fork: ForkSeq, attestation: Attestation): IndexedAttestation {
   916→    const {data} = attestation;
   917→    const attestingIndices = this.getAttestingIndices(fork, attestation);
   918→
   919→    // sort in-place
   920→    attestingIndices.sort((a, b) => a - b);
   921→    return {
   922→      attestingIndices: attestingIndices,
   923→      data: data,
   924→      signature: attestation.signature,
   925→    };
   926→  }
   927→
   928→  /**
   929→   * Return indices of validators who attestested in `attestation`
   930→   */
   931→  getAttestingIndices(fork: ForkSeq, attestation: Attestation): number[] {
   932→    if (fork < ForkSeq.electra) {
   933→      const {aggregationBits, data} = attestation;
   934→      const validatorIndices = this.getBeaconCommittee(data.slot, data.index);
   935→
   936→      return aggregationBits.intersectValues(validatorIndices);
   937→    }
   938→    const {aggregationBits, committeeBits, data} = attestation as electra.Attestation;
   939→
   940→    // There is a naming conflict on the term `committeeIndices`
   941→    // In Lodestar it usually means a list of validator indices of participants in a committee
   942→    // In the spec it means a list of committee indices according to committeeBits
   943→    // This `committeeIndices` refers to the latter
   944→    // TODO Electra: resolve the naming conflicts
   945→    const committeeIndices = committeeBits.getTrueBitIndexes();
   946→
   947→    const validatorsByCommittee = this.getBeaconCommittees(data.slot, committeeIndices);
   948→
   949→    // Create a new Uint32Array to flatten `validatorsByCommittee`
   950→    const totalLength = validatorsByCommittee.reduce((acc, curr) => acc + curr.length, 0);
   951→    const committeeValidators = new Uint32Array(totalLength);
   952→
   953→    let offset = 0;
   954→    for (const committee of validatorsByCommittee) {
   955→      committeeValidators.set(committee, offset);
   956→      offset += committee.length;
   957→    }
   958→
   959→    return aggregationBits.intersectValues(committeeValidators);
   960→  }
   961→
   962→  getCommitteeAssignments(
   963→    epoch: Epoch,
   964→    requestedValidatorIndices: ValidatorIndex[]
   965→  ): Map<ValidatorIndex, AttesterDuty> {
   966→    const shuffling = this.getShufflingAtEpoch(epoch);
   967→    return calculateCommitteeAssignments(shuffling, requestedValidatorIndices);
   968→  }
   969→
   970→  /**
   971→   * Return the committee assignment in the ``epoch`` for ``validator_index``.
   972→   * ``assignment`` returned is a tuple of the following form:
   973→   * ``assignment[0]`` is the list of validators in the committee
   974→   * ``assignment[1]`` is the index to which the committee is assigned
   975→   * ``assignment[2]`` is the slot at which the committee is assigned
   976→   * Return null if no assignment..
   977→   */
   978→  getCommitteeAssignment(epoch: Epoch, validatorIndex: ValidatorIndex): phase0.CommitteeAssignment | null {
   979→    if (epoch > this.currentShuffling.epoch + 1) {
   980→      throw Error(
   981→        `Requesting committee assignment for more than 1 epoch ahead: ${epoch} > ${this.currentShuffling.epoch} + 1`
   982→      );
   983→    }
   984→
   985→    const epochStartSlot = computeStartSlotAtEpoch(epoch);
   986→    const committeeCountPerSlot = this.getCommitteeCountPerSlot(epoch);
   987→    for (let slot = epochStartSlot; slot < epochStartSlot + SLOTS_PER_EPOCH; slot++) {
   988→      for (let i = 0; i < committeeCountPerSlot; i++) {
   989→        const committee = this.getBeaconCommittee(slot, i);
   990→        if (committee.includes(validatorIndex)) {
   991→          return {
   992→            validators: Array.from(committee),
   993→            committeeIndex: i,
   994→            slot,
   995→          };
   996→        }
   997→      }
   998→    }
   999→    return null;
  1000→  }
  1001→
  1002→  isAggregator(slot: Slot, index: CommitteeIndex, slotSignature: BLSSignature): boolean {
  1003→    const committee = this.getBeaconCommittee(slot, index);
  1004→    return isAggregatorFromCommitteeLength(committee.length, slotSignature);
  1005→  }
  1006→
  1007→  /**
  1008→   * Return pubkey given the validator index.
  1009→   */
  1010→  getPubkey(index: ValidatorIndex): PublicKey | undefined {
  1011→    return this.index2pubkey[index];
  1012→  }
  1013→
  1014→  getValidatorIndex(pubkey: Uint8Array): ValidatorIndex | null {
  1015→    return this.pubkey2index.get(pubkey);
  1016→  }
  1017→
  1018→  addPubkey(index: ValidatorIndex, pubkey: Uint8Array): void {
  1019→    this.pubkey2index.set(pubkey, index);
  1020→    this.index2pubkey[index] = PublicKey.fromBytes(pubkey); // Optimize for aggregation
  1021→  }
  1022→
  1023→  getShufflingAtSlot(slot: Slot): EpochShuffling {
  1024→    const epoch = computeEpochAtSlot(slot);
  1025→    return this.getShufflingAtEpoch(epoch);
  1026→  }
  1027→
  1028→  getShufflingAtSlotOrNull(slot: Slot): EpochShuffling | null {
  1029→    const epoch = computeEpochAtSlot(slot);
  1030→    return this.getShufflingAtEpochOrNull(epoch);
  1031→  }
  1032→
  1033→  getShufflingAtEpoch(epoch: Epoch): EpochShuffling {
  1034→    const shuffling = this.getShufflingAtEpochOrNull(epoch);
  1035→    if (shuffling === null) {
  1036→      if (epoch === this.nextEpoch) {
  1037→        throw new EpochCacheError({
  1038→          code: EpochCacheErrorCode.NEXT_SHUFFLING_NOT_AVAILABLE,
  1039→          epoch: epoch,
  1040→          decisionRoot: this.getShufflingDecisionRoot(this.nextEpoch),
  1041→        });
  1042→      }
  1043→      throw new EpochCacheError({
  1044→        code: EpochCacheErrorCode.COMMITTEE_EPOCH_OUT_OF_RANGE,
  1045→        currentEpoch: this.currentShuffling.epoch,
  1046→        requestedEpoch: epoch,
  1047→      });
  1048→    }
  1049→
  1050→    return shuffling;
  1051→  }
  1052→
  1053→  getShufflingDecisionRoot(epoch: Epoch): RootHex {
  1054→    switch (epoch) {
  1055→      case this.epoch - 1:
  1056→        return this.previousDecisionRoot;
  1057→      case this.epoch:
  1058→        return this.currentDecisionRoot;
  1059→      case this.nextEpoch:
  1060→        return this.nextDecisionRoot;
  1061→      default:
  1062→        throw new EpochCacheError({
  1063→          code: EpochCacheErrorCode.DECISION_ROOT_EPOCH_OUT_OF_RANGE,
  1064→          currentEpoch: this.epoch,
  1065→          requestedEpoch: epoch,
  1066→        });
  1067→    }
  1068→  }
  1069→
  1070→  getShufflingAtEpochOrNull(epoch: Epoch): EpochShuffling | null {
  1071→    switch (epoch) {
  1072→      case this.epoch - 1:
  1073→        return this.previousShuffling;
  1074→      case this.epoch:
  1075→        return this.currentShuffling;
  1076→      case this.nextEpoch:
  1077→        if (!this.nextShuffling) {
  1078→          this.nextShuffling =
  1079→            this.shufflingCache?.getSync(this.nextEpoch, this.getShufflingDecisionRoot(this.nextEpoch)) ?? null;
  1080→        }
  1081→        return this.nextShuffling;
  1082→      default:
  1083→        return null;
  1084→    }
  1085→  }
  1086→
  1087→  /**
  1088→   * Note: The range of slots a validator has to perform duties is off by one.
  1089→   * The previous slot wording means that if your validator is in a sync committee for a period that runs from slot
  1090→   * 100 to 200,then you would actually produce signatures in slot 99 - 199.
  1091→   */
  1092→  getIndexedSyncCommittee(slot: Slot): SyncCommitteeCache {
  1093→    // See note above for the +1 offset
  1094→    return this.getIndexedSyncCommitteeAtEpoch(computeEpochAtSlot(slot + 1));
  1095→  }
  1096→
  1097→  /**
  1098→   * **DO NOT USE FOR GOSSIP VALIDATION**: Sync committee duties are offset by one slot. @see {@link EpochCache.getIndexedSyncCommittee}
  1099→   *
  1100→   * Get indexed sync committee at epoch without offsets
  1101→   */
  1102→  getIndexedSyncCommitteeAtEpoch(epoch: Epoch): SyncCommitteeCache {
  1103→    switch (computeSyncPeriodAtEpoch(epoch)) {
  1104→      case this.syncPeriod:
  1105→        return this.currentSyncCommitteeIndexed;
  1106→      case this.syncPeriod + 1:
  1107→        return this.nextSyncCommitteeIndexed;
  1108→      default:
  1109→        throw new EpochCacheError({code: EpochCacheErrorCode.NO_SYNC_COMMITTEE, epoch});
  1110→    }
  1111→  }
  1112→
  1113→  /** On processSyncCommitteeUpdates rotate next to current and set nextSyncCommitteeIndexed */
  1114→  rotateSyncCommitteeIndexed(nextSyncCommitteeIndices: Uint32Array): void {
  1115→    this.currentSyncCommitteeIndexed = this.nextSyncCommitteeIndexed;
  1116→    this.nextSyncCommitteeIndexed = getSyncCommitteeCache(nextSyncCommitteeIndices);
  1117→  }
  1118→
  1119→  /** On phase0 -> altair fork, set both current and nextSyncCommitteeIndexed */
  1120→  setSyncCommitteesIndexed(nextSyncCommitteeIndices: Uint32Array): void {
  1121→    this.nextSyncCommitteeIndexed = getSyncCommitteeCache(nextSyncCommitteeIndices);
  1122→    this.currentSyncCommitteeIndexed = this.nextSyncCommitteeIndexed;
  1123→  }
  1124→
  1125→  effectiveBalanceIncrementsSet(index: number, effectiveBalance: number): void {
  1126→    if (this.isPostElectra()) {
  1127→      // TODO: electra
  1128→      // getting length and setting getEffectiveBalanceIncrementsByteLen is not fork safe
  1129→      // so each time we add an index, we should new the Uint8Array to keep it forksafe
  1130→      // one simple optimization could be to increment the length once per block rather
  1131→      // on each add/set
  1132→      //
  1133→      // there could still be some unused length remaining from the prev ELECTRA padding
  1134→      const newLength =
  1135→        index >= this.effectiveBalanceIncrements.length ? index + 1 : this.effectiveBalanceIncrements.length;
  1136→      const effectiveBalanceIncrements = this.effectiveBalanceIncrements;
  1137→      this.effectiveBalanceIncrements = new Uint16Array(newLength);
  1138→      this.effectiveBalanceIncrements.set(effectiveBalanceIncrements, 0);
  1139→    } else {
  1140→      if (index >= this.effectiveBalanceIncrements.length) {
  1141→        // Clone and extend effectiveBalanceIncrements
  1142→        const effectiveBalanceIncrements = this.effectiveBalanceIncrements;
  1143→        this.effectiveBalanceIncrements = new Uint16Array(getEffectiveBalanceIncrementsByteLen(index + 1));
  1144→        this.effectiveBalanceIncrements.set(effectiveBalanceIncrements, 0);
  1145→      }
  1146→    }
  1147→
  1148→    this.effectiveBalanceIncrements[index] = Math.floor(effectiveBalance / EFFECTIVE_BALANCE_INCREMENT);
  1149→  }
  1150→
  1151→  isPostElectra(): boolean {
  1152→    return this.epoch >= this.config.ELECTRA_FORK_EPOCH;
  1153→  }
  1154→}
  1155→
  1156→function getEffectiveBalanceIncrementsByteLen(validatorCount: number): number {
  1157→  // TODO: Research what's the best number to minimize both memory cost and copy costs
  1158→  return 1024 * Math.ceil(validatorCount / 1024);
  1159→}
  1160→
  1161→export enum EpochCacheErrorCode {
  1162→  COMMITTEE_INDEX_OUT_OF_RANGE = "EPOCH_CONTEXT_ERROR_COMMITTEE_INDEX_OUT_OF_RANGE",
  1163→  COMMITTEE_EPOCH_OUT_OF_RANGE = "EPOCH_CONTEXT_ERROR_COMMITTEE_EPOCH_OUT_OF_RANGE",
  1164→  DECISION_ROOT_EPOCH_OUT_OF_RANGE = "EPOCH_CONTEXT_ERROR_DECISION_ROOT_EPOCH_OUT_OF_RANGE",
  1165→  NEXT_SHUFFLING_NOT_AVAILABLE = "EPOCH_CONTEXT_ERROR_NEXT_SHUFFLING_NOT_AVAILABLE",
  1166→  NO_SYNC_COMMITTEE = "EPOCH_CONTEXT_ERROR_NO_SYNC_COMMITTEE",
  1167→  PROPOSER_EPOCH_MISMATCH = "EPOCH_CONTEXT_ERROR_PROPOSER_EPOCH_MISMATCH",
  1168→}
  1169→
  1170→type EpochCacheErrorType =
  1171→  | {
  1172→      code: EpochCacheErrorCode.COMMITTEE_INDEX_OUT_OF_RANGE;
  1173→      index: number;
  1174→      maxIndex: number;
  1175→    }
  1176→  | {
  1177→      code: EpochCacheErrorCode.COMMITTEE_EPOCH_OUT_OF_RANGE;
  1178→      requestedEpoch: Epoch;
  1179→      currentEpoch: Epoch;
  1180→    }
  1181→  | {
  1182→      code: EpochCacheErrorCode.DECISION_ROOT_EPOCH_OUT_OF_RANGE;
  1183→      requestedEpoch: Epoch;
  1184→      currentEpoch: Epoch;
  1185→    }
  1186→  | {
  1187→      code: EpochCacheErrorCode.NEXT_SHUFFLING_NOT_AVAILABLE;
  1188→      epoch: Epoch;
  1189→      decisionRoot: RootHex;
  1190→    }
  1191→  | {
  1192→      code: EpochCacheErrorCode.NO_SYNC_COMMITTEE;
  1193→      epoch: Epoch;
  1194→    }
  1195→  | {
  1196→      code: EpochCacheErrorCode.PROPOSER_EPOCH_MISMATCH;
  1197→      requestedEpoch: Epoch;
  1198→      currentEpoch: Epoch;
  1199→    };
  1200→
  1201→export class EpochCacheError extends LodestarError<EpochCacheErrorType> {}
  1202→
  1203→export function createEmptyEpochCacheImmutableData(
  1204→  chainConfig: ChainConfig,
  1205→  state: Pick<BeaconStateAllForks, "genesisValidatorsRoot">
  1206→): EpochCacheImmutableData {
  1207→  return {
  1208→    config: createBeaconConfig(chainConfig, state.genesisValidatorsRoot),
  1209→    // This is a test state, there's no need to have a global shared cache of keys
  1210→    pubkey2index: new PubkeyIndexMap(),
  1211→    index2pubkey: [],
  1212→  };
  1213→}
