     1→import {PublicKey} from "@chainsafe/blst";
     2→import {BeaconConfig} from "@lodestar/config";
     3→import {loadState} from "../util/loadState/loadState.js";
     4→import {EpochCache, EpochCacheImmutableData, EpochCacheOpts} from "./epochCache.js";
     5→import {RewardCache, createEmptyRewardCache} from "./rewardCache.js";
     6→import {
     7→  BeaconStateAllForks,
     8→  BeaconStateAltair,
     9→  BeaconStateBellatrix,
    10→  BeaconStateCapella,
    11→  BeaconStateDeneb,
    12→  BeaconStateElectra,
    13→  BeaconStateExecutions,
    14→  BeaconStateFulu,
    15→  BeaconStateGloas,
    16→  BeaconStatePhase0,
    17→} from "./types.js";
    18→
    19→export type BeaconStateCache = {
    20→  config: BeaconConfig;
    21→  epochCtx: EpochCache;
    22→  /** Count of clones created from this BeaconStateCache instance. readonly to prevent accidental usage downstream */
    23→  readonly clonedCount: number;
    24→  readonly clonedCountWithTransferCache: number;
    25→  readonly createdWithTransferCache: boolean;
    26→  proposerRewards: RewardCache;
    27→};
    28→
    29→type Mutable<T> = {
    30→  -readonly [P in keyof T]: T[P];
    31→};
    32→
    33→type BeaconStateCacheMutable = Mutable<BeaconStateCache>;
    34→
    35→/**
    36→ * `BeaconState` with various caches
    37→ *
    38→ * Currently contains the following:
    39→ * - The full list of network params, ssz types, and fork schedule
    40→ * - The ssz type for the state
    41→ * - The full merkle tree representation of the state
    42→ * - A cache of shufflings, committees, proposers, expanded pubkeys
    43→ * - A flat copy of validators (for fast access/iteration)
    44→ *
    45→ * ### BeaconState data representation tradeoffs:
    46→ *
    47→ * Requirements of a BeaconState:
    48→ * - Block processing and epoch processing be performant to not block the node. This functions requires to iterate over
    49→ *   very large arrays fast, while doing random mutations or big mutations. After them the state must be hashed.
    50→ *   Processing times: (ideal / current / maximum)
    51→ *   - block processing: 20ms / 200ms / 500ms
    52→ *   - epoch processing: 200ms / 2s / 4s
    53→ *
    54→ * - BeaconState must be memory efficient. Data should only be represented once in a succint manner. Uint8Arrays are
    55→ *   expensive, native types are not.
    56→ * - BeaconState must be hashed efficiently. Data must be merkelized before hashing so the conversion to merkelized
    57→ *   must be fast or be done already. It must must persist a hashing cache that should be structurally shared between
    58→ *   states for memory efficiency.
    59→ * - BeaconState raw data changes sparsingly, so it should be structurally shared between states for memory efficiency
    60→ *
    61→ * Summary of goals:
    62→ * - Structurally share data + hashing cache
    63→ * - Very fast read and iteration over large arrays
    64→ * - Fast bulk writes and somewhat fast single writes
    65→ * - Fast merkelization of data for hashing
    66→ *
    67→ * #### state.validators
    68→ *
    69→ * 91% of all memory merkelized is state.validators. In normal network conditions state.validators changes rarely.
    70→ * However for epoch processing the entire array must be iterated and read. So we need fast reads and slow writes.
    71→ * Tradeoffs to achieve that:
    72→ * - Represent leaf data with native JS types (deserialized form)
    73→ * - Use a single Tree for structurally sharing leaf data + hashing cache
    74→ * - Keep only the root cached on leaf nodes
    75→ * - Micro-optimizations (TODO):
    76→ *   - Keep also the root of the node above pubkey and withdrawal creds. Will never change
    77→ *   - Keep pubkey + withdrawal creds in the same Uint8Array
    78→ *   - Have a global pubkey + withdrawal creds Uint8Array global cache, like with the index2pubkey cache
    79→ *
    80→ * ------------------
    81→ *
    82→ * _Previous JSDocs for `BeaconStateContext`_
    83→ *
    84→ * Cache useful data associated to a specific state.
    85→ * Optimize processing speed of block processing + gossip validation while having a low memory cost.
    86→ *
    87→ * Previously BeaconStateContext included:
    88→ * ```ts
    89→ * validators: CachedValidatorList & T["validators"];
    90→ * balances: CachedBalanceList & T["balances"];
    91→ * inactivityScores: CachedInactivityScoreList & Number64[];
    92→ * ```
    93→ *
    94→ * Those caches where removed since they are no strictly necessary to make the epoch transition faster,
    95→ * but have a high memory cost. Note that all data was duplicated between the Tree and MutableVector.
    96→ * 1. TreeView, for efficient hashing
    97→ * 2. MutableVector (persistent-ts) with StructBacked validator objects for fast accessing and iteration
    98→ *
    99→ * ### validators
   100→ * state.validators is the heaviest data structure in the state. As TreeView, the leafs account for 91% with
   101→ * 200_000 validators. It requires ~ 2_000_000 Uint8Array instances with total memory of ~ 400MB.
   102→ * However its contents don't change very often. Validators only change when;
   103→ * - they first deposit
   104→ * - they dip from 32 effective balance to 31 (pretty much only when inactive for very long, or slashed)
   105→ * - they activate (once)
   106→ * - they exit (once)
   107→ * - they get slashed (max once)
   108→ *
   109→ * ### balances
   110→ * The balances array completely changes at the epoch boundary, where almost all the validator balances
   111→ * are updated. However it may have tiny changes during block processing if:
   112→ * - On a valid deposit
   113→ * - Validator gets slashed
   114→ * - On altair, the block proposer. Optimized to only happen once per block
   115→ *
   116→ * ### epochParticipation
   117→ * epochParticipation changes continuously through the epoch for each partipation bit of each valid attestation in the state.
   118→ * The entire structure is dropped after two epochs.
   119→ *
   120→ * ### inactivityScores
   121→ * inactivityScores can be changed only:
   122→ * - At the epoch transition. It only changes when a validator is offline. So it may change a bit but not
   123→ *   a lot on normal network conditions.
   124→ * - During block processing, when a validator joins a new 0 entry is pushed
   125→ *
   126→ * RESULT: Don't keep a duplicated structure around always. During block processing just push to the tree. During
   127→ * epoch processing some temporary flat structures are computed but dropped after processing the epoch.
   128→ */
   129→export type CachedBeaconState<T extends BeaconStateAllForks> = T & BeaconStateCache;
   130→
   131→export type CachedBeaconStatePhase0 = CachedBeaconState<BeaconStatePhase0>;
   132→export type CachedBeaconStateAltair = CachedBeaconState<BeaconStateAltair>;
   133→export type CachedBeaconStateBellatrix = CachedBeaconState<BeaconStateBellatrix>;
   134→export type CachedBeaconStateCapella = CachedBeaconState<BeaconStateCapella>;
   135→export type CachedBeaconStateDeneb = CachedBeaconState<BeaconStateDeneb>;
   136→export type CachedBeaconStateElectra = CachedBeaconState<BeaconStateElectra>;
   137→export type CachedBeaconStateFulu = CachedBeaconState<BeaconStateFulu>;
   138→export type CachedBeaconStateGloas = CachedBeaconState<BeaconStateGloas>;
   139→
   140→export type CachedBeaconStateAllForks = CachedBeaconState<BeaconStateAllForks>;
   141→export type CachedBeaconStateExecutions = CachedBeaconState<BeaconStateExecutions>;
   142→/**
   143→ * Create CachedBeaconState computing a new EpochCache instance
   144→ * TODO ELECTRA: rename this to createFinalizedCachedBeaconState() as it's intended for finalized state only
   145→ */
   146→export function createCachedBeaconState<T extends BeaconStateAllForks>(
   147→  state: T,
   148→  immutableData: EpochCacheImmutableData,
   149→  opts?: EpochCacheOpts
   150→): T & BeaconStateCache {
   151→  const epochCache = EpochCache.createFromState(state, immutableData, opts);
   152→  const cachedState = getCachedBeaconState(state, {
   153→    config: immutableData.config,
   154→    epochCtx: epochCache,
   155→    clonedCount: 0,
   156→    clonedCountWithTransferCache: 0,
   157→    createdWithTransferCache: false,
   158→    proposerRewards: createEmptyRewardCache(),
   159→  });
   160→
   161→  return cachedState;
   162→}
   163→
   164→/**
   165→ * Create a CachedBeaconState given a cached seed state and state bytes
   166→ * This guarantees that the returned state shares the same tree with the seed state
   167→ * Check loadState() api for more details
   168→ * // TODO: rename to loadUnfinalizedCachedBeaconState() due to ELECTRA
   169→ */
   170→export function loadCachedBeaconState<T extends BeaconStateAllForks & BeaconStateCache>(
   171→  cachedSeedState: T,
   172→  stateBytes: Uint8Array,
   173→  opts?: EpochCacheOpts,
   174→  seedValidatorsBytes?: Uint8Array
   175→): T {
   176→  const {state: migratedState, modifiedValidators} = loadState(
   177→    cachedSeedState.config,
   178→    cachedSeedState,
   179→    stateBytes,
   180→    seedValidatorsBytes
   181→  );
   182→  const {pubkey2index, index2pubkey, shufflingCache} = cachedSeedState.epochCtx;
   183→  // Get the validators sub tree once for all the loop
   184→  const validators = migratedState.validators;
   185→  for (const validatorIndex of modifiedValidators) {
   186→    const validator = validators.getReadonly(validatorIndex);
   187→    const pubkey = validator.pubkey;
   188→    pubkey2index.set(pubkey, validatorIndex);
   189→    index2pubkey[validatorIndex] = PublicKey.fromBytes(pubkey);
   190→  }
   191→
   192→  return createCachedBeaconState(
   193→    migratedState,
   194→    {
   195→      config: cachedSeedState.config,
   196→      pubkey2index,
   197→      index2pubkey,
   198→      shufflingCache,
   199→    },
   200→    {...(opts ?? {}), ...{skipSyncPubkeys: true}}
   201→  ) as T;
   202→}
   203→
   204→/**
   205→ * Attach an already computed BeaconStateCache to a BeaconState object
   206→ */
   207→export function getCachedBeaconState<T extends BeaconStateAllForks>(
   208→  state: T,
   209→  cache: BeaconStateCache
   210→): T & BeaconStateCache {
   211→  const cachedState = state as T & BeaconStateCache;
   212→  cachedState.config = cache.config;
   213→  cachedState.epochCtx = cache.epochCtx;
   214→  (cachedState as BeaconStateCacheMutable).clonedCount = cache.clonedCount;
   215→  (cachedState as BeaconStateCacheMutable).clonedCountWithTransferCache = cache.clonedCountWithTransferCache;
   216→  (cachedState as BeaconStateCacheMutable).createdWithTransferCache = cache.createdWithTransferCache;
   217→  cachedState.proposerRewards = cache.proposerRewards;
   218→
   219→  // Overwrite .clone function to preserve cache
   220→  // TreeViewDU.clone() creates a new object that does not have the attached cache
   221→  const viewDUClone = cachedState.clone.bind(cachedState);
   222→
   223→  function clone(this: T & BeaconStateCache, dontTransferCache?: boolean): T & BeaconStateCache {
   224→    const viewDUCloned = viewDUClone(dontTransferCache);
   225→
   226→    // Override `readonly` attribute in single place where `.clonedCount` is incremented
   227→    (this as BeaconStateCacheMutable).clonedCount++;
   228→
   229→    if (!dontTransferCache) {
   230→      (this as BeaconStateCacheMutable).clonedCountWithTransferCache++;
   231→    }
   232→
   233→    return getCachedBeaconState(viewDUCloned, {
   234→      config: this.config,
   235→      epochCtx: this.epochCtx.clone(),
   236→      clonedCount: 0,
   237→      clonedCountWithTransferCache: 0,
   238→      createdWithTransferCache: !dontTransferCache,
   239→      proposerRewards: createEmptyRewardCache(), // this sets the rewards to 0 while cloning new state
   240→    }) as T & BeaconStateCache;
   241→  }
   242→
   243→  cachedState.clone = clone as typeof viewDUClone;
   244→
   245→  return cachedState;
   246→}
   247→
   248→/**
   249→ * Typeguard to check if a state contains a BeaconStateCache
   250→ */
   251→export function isCachedBeaconState<T extends BeaconStateAllForks>(
   252→  state: T | (T & BeaconStateCache)
   253→): state is T & BeaconStateCache {
   254→  return (state as T & BeaconStateCache).epochCtx !== undefined;
   255→}
   256→
   257→// Given a CachedBeaconState, check if validators array internal cache is populated.
   258→// This cache is populated during epoch transition, and should be preserved for performance.
   259→// If the cache is missing too often, means that our clone strategy is not working well.
   260→export function isStateValidatorsNodesPopulated(state: CachedBeaconStateAllForks): boolean {
   261→  // biome-ignore lint/complexity/useLiteralKeys: It is a private attribute
   262→  return state.validators["nodesPopulated"] === true;
   263→}
   264→
   265→export function isStateBalancesNodesPopulated(state: CachedBeaconStateAllForks): boolean {
   266→  // biome-ignore lint/complexity/useLiteralKeys: It is a private attribute
   267→  return state.balances["nodesPopulated"] === true;
   268→}
   269→

