   745→   * At fork boundary, this runs post-fork logic and it happens after `upgradeState*` is called.
   746→   */
   747→  finalProcessEpoch(state: CachedBeaconStateAllForks): void {
   748→    // this.epoch was updated at the end of afterProcessEpoch()
   749→    const upcomingEpoch = this.epoch;
   750→    const epochAfterUpcoming = upcomingEpoch + 1;
   751→
   752→    this.proposersPrevEpoch = this.proposers;
   753→    if (upcomingEpoch >= this.config.FULU_FORK_EPOCH) {
   754→      // Populate proposer cache with lookahead from state
   755→      const proposerLookahead = (state as CachedBeaconStateFulu).proposerLookahead.getAll();
   756→      this.proposers = proposerLookahead.slice(0, SLOTS_PER_EPOCH);
   757→
   758→      if (proposerLookahead.length >= SLOTS_PER_EPOCH * 2) {
   759→        this.proposersNextEpoch = {
   760→          computed: true,
   761→          indexes: proposerLookahead.slice(SLOTS_PER_EPOCH, SLOTS_PER_EPOCH * 2),
   762→        };
   763→      } else {
   764→        // This should not happen unless MIN_SEED_LOOKAHEAD is set to 0
   765→        // this ensures things don't break if the proposer lookahead is not long enough
   766→        this.proposersNextEpoch = {computed: false, seed: getSeed(state, epochAfterUpcoming, DOMAIN_BEACON_PROPOSER)};
   767→      }
   768→    } else {
   769→      // Need to calculate proposers pre-fulu
   770→      const upcomingProposerSeed = getSeed(state, upcomingEpoch, DOMAIN_BEACON_PROPOSER);
   771→      // next epoch was moved to current epoch so use current here
   772→      this.proposers = computeProposers(
   773→        this.config.getForkSeqAtEpoch(upcomingEpoch),
   774→        upcomingProposerSeed,
   775→        this.currentShuffling,
   776→        this.effectiveBalanceIncrements
   777→      );
   778→      // Only pre-compute the seed since it's very cheap. Do the expensive computeProposers() call only on demand.
   779→      this.proposersNextEpoch = {computed: false, seed: getSeed(state, epochAfterUpcoming, DOMAIN_BEACON_PROPOSER)};
